```mermaid
flowchart TD
  A[Need to report a failure] --> B{Fixed message only?}
  B -- Yes --> C[errors.New]
  B -- No --> D{Need underlying cause?}
  D -- Yes --> E[fmt.Errorf with percent w]
  D -- No --> F{Caller needs fields?}
  F -- Yes --> G[Custom error type]
  F -- No --> H[fmt.Errorf for dynamic text]
```

```go
package main

import (
    "errors"
    "fmt"
)

func validateName(name string) error {
    if name == "" {
        return errors.New("name is required")
    }
    return nil
}

func main() {
    fmt.Println(validateName(""))
    fmt.Println(validateName("Ada"))
}
```
The first call prints `name is required`; the second prints `<nil>` because no error is needed.

```go
package main

import (
    "errors"
    "fmt"
)

var ErrNotFound = errors.New("not found")

func findUser(id int) error {
    return fmt.Errorf("user %d: %w", id, ErrNotFound)
}

func main() {
    err := findUser(42)
    fmt.Println(err)
    fmt.Println(errors.Is(err, ErrNotFound))
}
```
The message retains user `42`, and the identity check prints `true` through the wrapper.

```go
package main

import (
    "errors"
    "fmt"
)

var ErrClosed = errors.New("closed")

func main() {
    first := errors.New("closed")
    second := errors.New("closed")
    wrapped := fmt.Errorf("send message: %w", ErrClosed)

    fmt.Println(first == second)
    fmt.Println(errors.Is(wrapped, ErrClosed))
}
```
The output is `false` and `true`: identical wording is not identity, while wrapping preserves a deliberate category.
